//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
	"github.com/stretchr/testify/require"
)

func TestEnum_SAFETY_SWITCH_STATE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.SAFETY_SWITCH_STATE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.SAFETY_SWITCH_STATE_SAFE.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.SAFETY_SWITCH_STATE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.SAFETY_SWITCH_STATE_SAFE, dec)
	})
}
